def svg_for(index: int, title: str, category: str) -> str:
    palettes = [
        ("#0b2b40", "#23c99c", "#e8f8f2"),
        ("#102c55", "#1784fc", "#eaf3ff"),
        ("#3b244b", "#f08a5d", "#fff0e9"),
        ("#183b35", "#b4e86c", "#effbd9"),
        ("#24304f", "#efc35c", "#fff7db"),
    ]
    ink, accent, soft = palettes[index % len(palettes)]
    motif = index % 5
    shapes = {
        0: f'<circle cx="660" cy="90" r="250" fill="{accent}" opacity=".18"/><path d="M470 450c120-180 300-210 390-60s-34 230-210 220-270-8-180-160Z" fill="{accent}" opacity=".38"/>',
        1: f'<path d="M520 30h250v250H520z" rx="44" fill="{accent}" opacity=".25" transform="rotate(18 645 155)"/><path d="M460 520 760 230l105 105-300 290z" fill="{accent}" opacity=".42"/>',
        2: f'<circle cx="670" cy="210" r="160" fill="none" stroke="{accent}" stroke-width="34" opacity=".45"/><circle cx="670" cy="210" r="75" fill="{accent}" opacity=".75"/><path d="M420 535c70-115 170-170 300-165 130 5 210 60 265 165" fill="none" stroke="{accent}" stroke-width="26" opacity=".42"/>',
        3: f'<path d="M455 120 650 30l210 110-190 110-215-130Z" fill="{accent}" opacity=".36"/><path d="M455 120v205l210 115V250L455 120Z" fill="{accent}" opacity=".22"/><path d="M665 250v190l195-115V140L665 250Z" fill="{accent}" opacity=".5"/>',
        4: f'<path d="M430 410c0-190 90-300 235-300s235 110 235 300" fill="none" stroke="{accent}" stroke-width="42" opacity=".35"/><path d="M475 460c95-90 205-115 330-75" fill="none" stroke="{accent}" stroke-width="34" opacity=".72"/>',
    }[motif]
    safe_title = escape(title[:28])
    safe_category = escape(category.upper())
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 600" role="img" aria-labelledby="title desc">
  <title id="title">{safe_title}</title><desc id="desc">PayPilot editorial illustration for {safe_category.lower()}.</desc>
  <rect width="900" height="600" rx="42" fill="{soft}"/><rect x="34" y="34" width="832" height="532" rx="30" fill="none" stroke="{ink}" stroke-opacity=".12" stroke-width="2"/>
  {shapes}<text x="70" y="88" fill="{ink}" font-family="Arial, sans-serif" font-size="20" font-weight="700" letter-spacing="3">PAYPILOT / {safe_category}</text>
  <text x="70" y="505" fill="{ink}" font-family="Arial, sans-serif" font-size="35" font-weight="700">{safe_title}</text><circle cx="790" cy="500" r="22" fill="{accent}"/><circle cx="790" cy="500" r="8" fill="{soft}"/>
</svg>'''


