def article(post, index: int) -> str:
    slug, title, keyword, category, summary, audience, look_for, method, features = post
    generated_image = generated_image_for(slug, index, category)
    related = [POSTS[(index + 1) % len(POSTS)], POSTS[(index + 7) % len(POSTS)], POSTS[(index + 13) % len(POSTS)]]
    feature_html = "".join(f"<li>{escape(item)}</li>" for item in features)
    related_html = "".join(f'<a class="card card-link" href="{r[0]}.html"><span class="eyebrow">{escape(r[3])}</span><h3>{escape(r[1])}</h3><p>{escape(r[4])}</p></a>' for r in related)
    faq = [
        (f"What should I look for when choosing {keyword.lower()}?", f"Look for the workflow that matches your real payments: {look_for.lower()} The right tool should be understandable, editable, and easy to keep current."),
        ("Can PayPilot replace my bank statement or financial adviser?", "No. PayPilot is an organisation and tracking tool. Keep official statements and use a qualified professional for personalised financial, tax, or investment advice."),
        (f"How do I get started with {keyword.lower()}?", f"Start with one month of records, add your recurring commitments, and review the result once a week. {method}")
    ]
    faq_html = "".join(f"<details><summary>{escape(q)}</summary><p>{escape(a)}</p></details>" for q, a in faq)
    desc = escape(summary[:155])
    image = f"{BASE_URL}/{generated_image}"
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{desc}"><meta name="robots" content="index,follow"><link rel="canonical" href="{BASE_URL}/blog/{slug}.html"><meta property="og:type" content="article"><meta property="og:title" content="{escape(title)} — PayPilot"><meta property="og:description" content="{desc}"><meta property="og:url" content="{BASE_URL}/blog/{slug}.html"><meta property="og:image" content="{image}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title)} — PayPilot"><meta name="twitter:description" content="{desc}"><meta name="twitter:image" content="{image}"><title>{escape(title)} — PayPilot</title><link rel="stylesheet" href="../styles.css"><script type="application/ld+json">{json_ld_article(title, summary, slug, category, image)}</script><script type="application/ld+json">{json_ld_breadcrumb(title, slug)}</script></head>
<body>{header("../", "page")}<main class="page-shell"><article class="blog-article"><div class="blog-hero"><div><span class="eyebrow">{escape(category)} · PayPilot money guide</span><h1>{escape(title)}</h1><p class="lede">{escape(summary)}</p><p class="meta"><strong>Primary search phrase:</strong> {escape(keyword)} · Updated {DATE}</p></div><img class="blog-art" src="../{generated_image}" alt="Editorial illustration about {escape(keyword.lower())}" width="800" height="1417"></div><div class="blog-layout"><aside class="toc" aria-label="On this page"><strong>On this page</strong><a href="#quick-answer">Quick answer</a><a href="#what-to-look-for">What to look for</a><a href="#how">How to approach it</a><a href="#paypilot">Where PayPilot fits</a><a href="#faq">FAQ</a></aside><div class="legal-content"><section id="quick-answer"><h2>Quick answer</h2><p>{escape(audience)} For this kind of money workflow, the useful test is whether the tool reduces repetitive work while keeping your records explainable. It should show the important context behind a transaction instead of turning your finances into a black box.</p><div class="callout"><p><strong>The useful test:</strong> Can you understand what happened, correct it when needed, and see how it affects the rest of the month?</p></div></section><section id="what-to-look-for"><h2>What to look for</h2><p>Before choosing a tool, check whether it supports the details that make your money life different from a generic demo:</p><ul>{feature_html}</ul><p>{escape(look_for)} The best choice is usually the one that makes these details visible without forcing you into a complicated setup.</p></section><section id="how"><h2>A practical way to approach it</h2><p>{escape(method)}</p><ol class="steps"><li>Collect one complete period of transactions, including cash, recurring bills, and transfers.</li><li>Separate money going out from money moving between your own accounts.</li><li>Review categories and merchants, then correct the few records that need context.</li><li>Use the result to choose one small change for the next period.</li></ol></section><section id="paypilot"><h2>Where PayPilot fits</h2><p>PayPilot is designed as a local-first personal finance organiser for expenses, payments, subscriptions, loans, reminders, and income. It supports manual records and, where the device flow allows it, automatic capture from bank messages, notifications, or Apple Pay Shortcuts.</p><p>The app keeps the original transaction context, supports multiple currencies, and gives you a way to review monthly outflow, commitments, repayments, and—when enabled—money coming in. Availability depends on your device, operating-system permissions, and the specific payment alert.</p><div class="grid blog-feature-grid"><div class="card"><h3>Capture</h3><p>Reduce repetitive entry while keeping manual correction available.</p></div><div class="card"><h3>Understand</h3><p>See categories, recurring commitments, loans, and cash flow together.</p></div><div class="card"><h3>Control</h3><p>Keep permissions, sync, export, and deletion choices visible.</p></div></div></section><section id="faq"><h2>Frequently asked questions</h2><div class="faq-list">{faq_html}</div></section><section><div class="callout warning"><p><strong>Important:</strong> PayPilot is a tracking and organisation tool, not a bank, lender, tax adviser, or investment adviser. Verify important information against official records.</p></div></section></div></div></article><section class="section"><div class="section-head"><span class="eyebrow">Keep reading</span><h2>Related money guides</h2></div><div class="grid">{related_html}</div></section></main>{footer("../")}<script src="../script.js"></script></body></html>'''


def json_ld_article(title: str, summary: str, slug: str, category: str, image: str) -> str:
    return escape_json({"@context": "https://schema.org", "@type": "Article", "headline": title, "description": summary, "image": [image], "datePublished": DATE, "dateModified": DATE, "author": {"@type": "Organization", "name": "PayPilot"}, "publisher": {"@type": "Organization", "name": "AppGenie", "logo": {"@type": "ImageObject", "url": f"{BASE_URL}/paypilot_logo.png"}}, "articleSection": category, "mainEntityOfPage": f"{BASE_URL}/blog/{slug}.html"})


def json_ld_breadcrumb(title: str, slug: str) -> str:
    return escape_json({"@context": "https://schema.org", "@type": "BreadcrumbList", "itemListElement": [{"@type": "ListItem", "position": 1, "name": "PayPilot", "item": BASE_URL}, {"@type": "ListItem", "position": 2, "name": "Money guides", "item": f"{BASE_URL}/blog/"}, {"@type": "ListItem", "position": 3, "name": title, "item": f"{BASE_URL}/blog/{slug}.html"}]})


def escape_json(value: dict) -> str:
    import json
    return json.dumps(value, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")


def filter_tags(category: str) -> str:
    tags = {"Tracking"}
    if any(term in category.lower() for term in ("uae", "dubai", "aed", "expat", "nri")):
        tags.add("UAE")
    if any(term in category.lower() for term in ("india", "upi", "nri")):
        tags.add("India")
    if "privacy" in category.lower() or "safety" in category.lower():
        tags.add("Privacy")
    if any(term in category.lower() for term in ("comparison", "alternative")):
        tags.add("Comparisons")
    return " ".join(sorted(tags))


def generated_image_for(slug: str, index: int, category: str) -> str:
    unique_path = f"images/blog-generated/{slug}.png"
    if (ROOT / unique_path).exists():
        return unique_path
    category_lower = category.lower()
    if any(term in category_lower for term in ("subscription", "bill", "budget", "planning")):
        return GENERATED_IMAGES["subscriptions" if "subscription" in category_lower else "budgeting"]
    if any(term in category_lower for term in ("loan", "credit")):
        return GENERATED_IMAGES["loans"]
    if any(term in category_lower for term in ("privacy", "safety")):
        return GENERATED_IMAGES["privacy"]
    if any(term in category_lower for term in ("spend", "expense", "cash flow", "tracking", "aed", "income")):
        return GENERATED_IMAGES["spending"]
    return list(GENERATED_IMAGES.values())[index % len(GENERATED_IMAGES)]


def blog_index() -> str:
    cards = "".join(f'<a class="card card-link blog-card" data-category="{filter_tags(p[3])}" href="{p[0]}.html"><img src="../{generated_image_for(p[0], i, p[3])}" alt="Editorial illustration about {escape(p[1])}" width="800" height="1417" loading="lazy"><span class="eyebrow">{escape(p[3])}</span><h2>{escape(p[1])}</h2><p>{escape(p[4])}</p><span class="read-more">Read guide →</span></a>' for i, p in enumerate(POSTS))
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Practical PayPilot guides for expense tracking, budgets, bank SMS, UPI, AED spending, loans, subscriptions, privacy, and personal cash flow."><meta name="robots" content="index,follow"><link rel="canonical" href="{BASE_URL}/blog/"><meta property="og:type" content="website"><meta property="og:title" content="PayPilot money guides"><meta property="og:description" content="Practical guides for clearer everyday money tracking."><meta property="og:url" content="{BASE_URL}/blog/"><title>Money guides — PayPilot</title><link rel="stylesheet" href="../styles.css"><script type="application/ld+json">{escape_json({"@context": "https://schema.org", "@type": "WebSite", "name": "PayPilot", "url": BASE_URL})}</script></head><body>{header("../", "page")}<main><section class="page-hero page-shell"><span class="eyebrow">PayPilot money guides</span><h1>Clearer answers for everyday money.</h1><p>Practical, plain-language guides about expense tracking, budgets, bank alerts, UPI, AED spending, loans, subscriptions, privacy, and cash flow.</p><div class="blog-filter" role="group" aria-label="Filter guides"><button class="filter-button is-active" type="button" data-filter="all">All guides</button><button class="filter-button" type="button" data-filter="UAE">UAE</button><button class="filter-button" type="button" data-filter="India">India</button><button class="filter-button" type="button" data-filter="Privacy">Privacy</button><button class="filter-button" type="button" data-filter="Tracking">Tracking</button><button class="filter-button" type="button" data-filter="Comparisons">Comparisons</button></div></section><section class="section page-shell"><div class="blog-grid">{cards}</div></section></main>{footer("../")}<script src="../script.js"></script><script>document.querySelectorAll('[data-filter]').forEach(function(button){{button.addEventListener('click',function(){{document.querySelectorAll('[data-filter]').forEach(function(item){{item.classList.remove('is-active')}});button.classList.add('is-active');var filter=button.dataset.filter;document.querySelectorAll('.blog-card').forEach(function(card){{card.hidden=filter!=='all' && card.dataset.category.split(' ').indexOf(filter)===-1}})}})}});</script></body></html>'''


def sitemap() -> str:
    urls = ["", "privacy.html", "terms.html", "faq.html", "delete-account.html", "auto-capture.html", "support.html", "blog/"] + [f"blog/{p[0]}.html" for p in POSTS]
    body = "".join(f"<url><loc>{BASE_URL}/{u}</loc><lastmod>{DATE}</lastmod></url>" for u in urls)
    return f'<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">{body}</urlset>\n'


def main() -> None:
    BLOG.mkdir(exist_ok=True)
    IMAGES.mkdir(parents=True, exist_ok=True)
    for index, post in enumerate(POSTS):
        (BLOG / f"{post[0]}.html").write_text(article(post, index), encoding="utf-8")
        (IMAGES / f"{post[0]}.svg").write_text(svg_for(index, post[1], post[3]), encoding="utf-8")
    (BLOG / "index.html").write_text(blog_index(), encoding="utf-8")
    (ROOT / "sitemap.xml").write_text(sitemap(), encoding="utf-8")
    (ROOT / "robots.txt").write_text(f"User-agent: *\nAllow: /\nSitemap: {BASE_URL}/sitemap.xml\n", encoding="utf-8")


if __name__ == "__main__":
    main()
